window.__BUNDLE__={"generatedAt":"2026-08-24T02:15:35.603871+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-08-17","archiveCutoff":"2021-08-25","addedToday":250,"addedThisRun":250,"fetchStats":{"hf":205,"arxiv":1124,"total":1329},"freshness":{"latestPaperDate":"2026-08-24","latestPublishedDate":"2026-08-24","latestBatchCount":215,"newInLast24h":250,"newInLast48h":567},"historyTotal":8207,"topicCounts":{"Multi-Agent":1628,"Evaluation":4135,"Planning":772,"Memory":187,"Code Agent":451,"Interpretability":275,"Agentic RAG":887,"Agentic Search":1067,"RL for LLM":661,"Reasoning":2636,"Hallucination":517,"Post-Training":1235,"Alignment":1085,"World Model":85,"Tool Use":981,"Agent Safety":1934,"Computer Use":192,"Reflection":373,"VLM Training":339,"LLM Training":887,"Fine-tuning":1178,"Multimodal Agent":51,"Agent Framework":600,"Error Attribution":72,"Data Engine":181},"count":36,"recentTotal":1372,"archiveCount":0,"archiveTotal":6835,"sources":{"hf":85,"arxiv":1280,"semanticScholar":7},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"source":"hf","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.21278","submittedDate":"2026-08-21","title":"CLEAR: Continuous Latent Adapter Routing for Utility-Preserving LLM Safety Alignment","pdf":"https://arxiv.org/pdf/2608.21278.pdf","url":"https://arxiv.org/abs/2608.21278","hfUrl":"https://huggingface.co/papers/2608.21278","topics":["Agent Safety","LLM Training","Evaluation","Alignment","Fine-tuning"],"authors":["Chengxiao Wang","Enyi Jiang","Xiaojing Liao","Sanmi Koyejo"],"tags":["Agent Safety","LLM Training","Evaluation","Alignment","Fine-tuning"],"announceDate":"2026-08-24","id":"arxiv:2608.21278","abstract":"Improving the safety of large language models (LLMs) often comes at the expense of utility, as globally applied safety tuning may affect model responses to both harmful and benign inputs. We propose \\textbf{C}ontinuous \\textbf{L}at\\textbf{E}nt \\textbf{A}dapter \\textbf{R}outing (CLEAR), a conditional safety adaptation framework that uses a lightweight hidden-state gate to continuously control the activation strength of a safety low-rank adapter. CLEAR aims to reduce harmful completions while avoiding unnecessary changes to the frozen backbone that could degrade performance on benign prompts. Experiments on widely used safety and utility benchmarks show that CLEAR improves robustness on HarmBench while reducing the utility degradation observed with globally applied safety tuning such as SFT or standard low-rank adaptation (LoRA). On Llama-3-8B-Instruct, CLEAR reduces HarmBench ASR from 32."},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.21305","submittedDate":"2026-08-21","title":"Re$^3$Cap: Retrieval-Guided Refinement for Image Captioning Enhancement via Reinforcement Learning","pdf":"https://arxiv.org/pdf/2608.21305.pdf","url":"https://arxiv.org/abs/2608.21305","topics":["Post-Training","LLM Training","VLM Training","Reasoning","Hallucination","Evaluation","Fine-tuning","RL for LLM"],"authors":["Haonan Jia","Shichao Dong","Zenghui Sun","Jiawen Zheng","Ziqi Miao","Gege Shi","Qiuyu Zhao","Jinsong Lan","Xiaoyong Zhu","Bo Zheng"],"tags":["Post-Training","LLM Training","VLM Training","Reasoning","Hallucination"],"announceDate":"2026-08-24","id":"arxiv:2608.21305","abstract":"Reinforcement Learning (RL) has demonstrated significant gains in image captioning, yet it is still limited in encouraging Large Vision-Language Models (LVLMs) to explore novel reasoning strategies. This limitation leads to a performance gap between RL and Supervised Fine-Tuning (SFT). In this paper, we argue that multi-modal retrieval can serve as an effective reasoning signal for caption refinement. Based on this insight, we present the Retrieval-Guided Refinement for Image Captioning (Re$^3$Cap), a retrieval-guided reasoning strategy that enhances image captioning without requiring additional annotations. Instantiated by Caption Refinement Suggester (CRS) and Caption Quality Assessor (CQA), this strategy identifies hallucinations and omissions in image captions, leading to more accurate and detailed descriptions. Extensive experiments demonstrate the superiority of our method in image"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20699","submittedDate":"2026-08-21","title":"ArtiMo: Agent-Driven Articulated Mesh Animation","pdf":"https://arxiv.org/pdf/2608.20699.pdf","url":"https://arxiv.org/abs/2608.20699","topics":["LLM Training","VLM Training","Reasoning","Planning","Evaluation","Fine-tuning","Reflection"],"authors":["Chunyu Zou","Peng Dai","Yi-Hua Huang","Ze Yuan","Jingwei Huang","Yeming Yao","Xiaojuan Qi"],"tags":["LLM Training","VLM Training","Reasoning","Planning","Evaluation"],"announceDate":"2026-08-24","id":"arxiv:2608.20699","abstract":"Animating articulated 3D meshes via text requires satisfying strict kinematic constraints, modeling causal interactions between parts, and achieving instruction fidelity. Due to the absence of task-specific training data and explicit articulation supervision, existing data-driven mesh animation methods are largely inapplicable to this setting. To address this, we propose ArtiMo, a novel agent-driven framework for text-guided articulated mesh animation. Operating in a zero-shot manner, ArtiMo develops an agentic pipeline powered by Large Language and Vision-Language Models (LLMs/VLMs) to orchestrate motion generation. By synergizing the explicit kinematic constraints of URDF with the agent's reasoning and planning capabilities, it effectively produces causally coherent part motions and interactions without requiring model fine-tuning. To ensure motion correctness, the agent additionally u"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20771","submittedDate":"2026-08-21","title":"CAS: Conformalized Agentic Search via Adaptive Retrieval and Policy Weighting","pdf":"https://arxiv.org/pdf/2608.20771.pdf","url":"https://arxiv.org/abs/2608.20771","topics":["Agentic Search","Post-Training","Reasoning","Hallucination","Fine-tuning","RL for LLM"],"authors":["Zixi Zhu","Jiayuan Su","Jian Zhang","Yu Lin","Hongwei Wang"],"tags":["Agentic Search","Post-Training","Reasoning","Hallucination","Fine-tuning"],"announceDate":"2026-08-24","id":"arxiv:2608.20771","abstract":"Search Agents face a severe reliability crisis during reinforcement learning (RL) fine-tuning. Heuristic Top-K retrieval often causes critical evidence loss or noise inclusion, while over-confidence induced by progressive RL leads to hallucinated answers and redundant searches. To build highly reliable agents, we introduce Conformal Prediction (CP) and propose Conformalized Agentic Search (CAS). This framework establishes reliability guarantees on both the retrieval and training sides: on the retrieval side, an Adaptive Prediction Set (APS), a specific CP realization, translates statistical coverage into dynamic document truncation to construct prediction sets that are adaptive in size; on the training side, Adaptive Conformal Inference (ACI), a dynamic CP algorithm, dynamically constructs prediction sets with controllable coverage to quantify answer confidence, which is then used to pen"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.21170","submittedDate":"2026-08-21","title":"Is Visual Prompting All You Need? Studying VLM Spatial Reasoning under Progressive Visual Scaffolds","pdf":"https://arxiv.org/pdf/2608.21170.pdf","url":"https://arxiv.org/abs/2608.21170","topics":["Post-Training","VLM Training","Reasoning","Planning","Evaluation"],"authors":["Lars Benedikt Kaesberg","Tianyu Yang","Florian Valentin Wunderlich","Terry Ruas","Jan Philip Wahle","Daniel Kurzawe","Bela Gipp"],"tags":["Post-Training","VLM Training","Reasoning","Planning","Evaluation"],"announceDate":"2026-08-24","id":"arxiv:2608.21170","abstract":"Vision-language models (VLMs) have advanced rapidly in multimodal reasoning, yet recent work shows that their failures often reflect an interaction between visual grounding and downstream reasoning. What remains less clear is how the visual presentation of a task shapes model performance and failure modes when the underlying reasoning problem is unchanged. We study this question in SPaRC, a benchmark for grid-based visual spatial planning, by introducing lightweight input-side scaffolds that preserve the visual modality while making spatial structure more accessible. Across multiple VLMs, these scaffolds improve task accuracy over the original visual setting by up to 34.0 percentage points and further complement GRPO-based training, yielding up to 4.6 additional accuracy points compared with near-zero gains on the original visual input. Analyses on both end-to-end task solving and object"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20634","submittedDate":"2026-08-21","title":"AgentMercury: Your Agent Can Synthesize Verifiable Environments for Business Scenarios at scale","pdf":"https://arxiv.org/pdf/2608.20634.pdf","url":"https://arxiv.org/abs/2608.20634","topics":["Tool Use","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"authors":["Minbyul Jeong","Chanwoong Yoon"],"tags":["Tool Use","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"announceDate":"2026-08-24","id":"arxiv:2608.20634","abstract":"Agents learn to act through interaction with environments, yet the environments used for training are often manually constructed or synthesized around predefined tasks and benchmarks. This task-centric paradigm makes it difficult to scale environments that reflect realistic and evolving workflows where diverse tasks can naturally emerge from the underlying world. We introduce AgentMercury, a scalable framework for synthesizing executable environments from high-level business scenarios. Rather than constructing an environment for a specific task, AgentMercury first instantiates a persistent world with entities, services, tools, state, and executable cross-service invariants, from which diverse tasks and interaction trajectories can subsequently emerge. We construct 4,783 executable environments spanning 14 industries and 50 countries, and use them as training substrates for reinforcement "},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20627","submittedDate":"2026-08-20","title":"When Failures Propagate: Causal Failure Attribution in Agentic Retrieval-Augmented Generation","pdf":"https://arxiv.org/pdf/2608.20627.pdf","url":"https://arxiv.org/abs/2608.20627","topics":["Agentic RAG","Agentic Search","Error Attribution","Reasoning","Evaluation"],"authors":["Lauren Pothuru"],"tags":["Agentic RAG","Agentic Search","Error Attribution","Reasoning","Evaluation"],"announceDate":"2026-08-24","id":"arxiv:2608.20627","abstract":"Agentic retrieval-augmented generation (RAG) interleaves retrieval, reasoning, and answer generation across multiple hops. A retrieval error at hop 1 can surface only as a wrong answer at hop 3, while later retrieval can also repair the trajectory. This paper introduces AgenticRAG-FP, an interventional benchmark for causal failure attribution in agentic RAG. The benchmark injects a certified fault at a specified hop, re-executes the downstream trajectory, and evaluates diagnosers against the known intervention. Its central question is whether a post-hoc trace still identifies the injected hop after the suffix changes. In the completed strict dense Claude Haiku 4.5 sweep on 80 three-hop MuSiQue questions, coverage-based diagnosis is 0.91 at hop 1 and 0.00 at hops 2 and 3 (n=43,36,21 failed trajectories). A smaller content-corruption study changes an answer-bearing or bridge fact in topica"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20381","submittedDate":"2026-06-29","title":"EditPPT: Faithful Long-Deck Slide Editing via Structured Tool-Using Multi-Agent with Dual-Modal Validators","pdf":"https://arxiv.org/pdf/2608.20381.pdf","url":"https://arxiv.org/abs/2608.20381","topics":["Agent Safety","Multi-Agent","Code Agent","Evaluation","Agent Framework"],"authors":["Jiheon Kim","Kyudan Jung","Jaegul Choo"],"tags":["Agent Safety","Multi-Agent","Code Agent","Evaluation","Agent Framework"],"announceDate":"2026-08-24","id":"arxiv:2608.20381","abstract":"Automating slide editing requires simultaneously satisfying modification accuracy, preservation fidelity, and robustness to deck length. Existing LLM-based systems often fail on real-world presentation files because they rely on idealized intermediate representations or open-ended code generation, which are prone to cascading errors in long decks. We introduce EditPPT, a multi-agent framework that reformulates slide editing as a constrained tool-selection problem. By executing localized shape-level operations through the native PowerPoint COM interface, EditPPT narrows the LLM action space while preserving the application-resolved structure of user-authored decks. By separating validation across modalities, our dual-modal validation provides more robust assessment of both instruction fidelity and visual quality. We also present DeckEdit-Bench, a benchmark with 28 human-authored decks, 58"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20492","submittedDate":"2026-08-20","title":"Annotations as Rollouts: Efficient and Scalable Reinforcement Learning for Video MLLMs","pdf":"https://arxiv.org/pdf/2608.20492.pdf","url":"https://arxiv.org/abs/2608.20492","topics":["Post-Training","LLM Training","Reasoning","Evaluation","RL for LLM"],"authors":["Yunheng Li","Guohong Mu","Hao Li","Shengsheng Qian","Dingwen Zhang","Qibin Hou","Ming-Ming Cheng"],"tags":["Post-Training","LLM Training","Reasoning","Evaluation","RL for LLM"],"announceDate":"2026-08-24","id":"arxiv:2608.20492","abstract":"Multimodal large language models (MLLMs) have become a prevailing paradigm for unified video perception. However, post-training on large multi-task datasets remains challenging, as existing reinforcement learning methods sample on-policy groups with few high-quality rollouts even with costly chain-of-thought (CoT) generation. In this paper, we study the sample efficiency and scalability of RL post-training for video MLLMs and introduce OraRL. We identify an overlooked role for annotations: Beyond scoring rollouts, each can enter its on-policy group as an oracle rollout, a direct positive optimization target. Direct oracle integration, however, is nontrivial: a high-reward oracle raises the group baseline and inverts otherwise positive policy advantages, a failure we term advantage inversion. At the core of OraRL is a decoupled advantage estimator: policy rollouts determine an oracle-free"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.21180","submittedDate":"2026-08-21","title":"Toward Vision Language Model-based Assessment of Clinical Quality and Usability of LGE-MR Images for Cardiac Ablation Planning","pdf":"https://arxiv.org/pdf/2608.21180.pdf","url":"https://arxiv.org/abs/2608.21180","topics":["VLM Training","Reasoning","Planning","Evaluation","Fine-tuning"],"authors":["Bipasha Kundu","Abhishek Chaturvedi","Axel W. E. Wismueller","Richard Simon","Cristian A. Linte"],"tags":["VLM Training","Reasoning","Planning","Evaluation","Fine-tuning"],"announceDate":"2026-08-24","id":"arxiv:2608.21180","abstract":"LGE cardiac MRI is widely used for left atrial fibrosis assessment and ablation planning in atrial fibrillation patients as knowledge of fibrotic tissue regions identified from LGE-MRI is critical for catheter ablation. Often, poor quality images used during ablation planning can cause mis-localization of ablation targets, directly impacting procedure safety and outcome. The decision of whether a scan meets the minimum quality threshold for ablation planning is currently made informally by the reviewing radiologist and is not captured by any automated system, yet it is arguably the most safety-critical output of the image quality assessment (IQA) process. However, variations in image quality caused by noise, motion artifacts, and poor boundary definition significantly compromise the reliability of downstream segmentation and clinical decision-making tasks. Manual quality assessment by ex"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20378","submittedDate":"2026-06-27","title":"Truth Lies Deep: Countering Semantic Camouflage via Latent Intent Verification","pdf":"https://arxiv.org/pdf/2608.20378.pdf","url":"https://arxiv.org/abs/2608.20378","topics":["Agent Safety","Post-Training","LLM Training","Alignment"],"authors":["Md. Hasib Ur Rahman"],"tags":["Agent Safety","Post-Training","LLM Training","Alignment"],"announceDate":"2026-08-24","id":"arxiv:2608.20378","abstract":"Safety alignment in Large Language Models (LLMs) is often superficial, relying on refusal mechanisms that trigger only at the final stages of generation without erasing the foundational knowledge of harmful concepts acquired during pretraining. This study demonstrates that this architectural disconnect leaves models vulnerable to Semantic Camouflage -- adversarial attacks that wrap harmful intent in benign narrative contexts (e.g., creative writing), effectively bypassing standard input and output guardrails. By analyzing the latent activation trajectories of three distinct Small Language Model (SLM) families (Phi-3, Qwen2.5, and Gemma-2b) under adversarial stress, this research identifies a universal ``Intent Horizon'' -- a critical depth (typically 15--20\\% of total layers) where the model's distinct, pre-trained representation of harmful intent collapses as it contextualizes the query"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.21027","submittedDate":"2026-08-21","title":"Don't Solve, Just Compare: Tiny Advisors for Runtime Intervention in LLM Agents","pdf":"https://arxiv.org/pdf/2608.21027.pdf","url":"https://arxiv.org/abs/2608.21027","topics":["Tool Use","Reasoning","Planning","Evaluation"],"authors":["Yanze Jiang","Mingxuan Li","Yuhao Wang","Shengfang Zhai","Jiaheng Zhang"],"tags":["Tool Use","Reasoning","Planning","Evaluation"],"announceDate":"2026-08-24","id":"arxiv:2608.21027","abstract":"LLM agents are emerging as an important paradigm for real-world tasks that require reasoning, tool use, and sequential decision-making. As these agents operate over longer horizons, runtime intervention offers a way to improve reliability without retraining the underlying actor. Failure detection alone is insufficient. Effective intervention must also provide a useful direction for recovery. Existing approaches often rely on an expert solver or a critic that generates task-specific corrections, incurring either the cost of another capable solver or the capacity demands of a task-capable critic. We introduce Comparison-Only Tiny Advisor (COTA), a comparison-only framework for constructive runtime intervention. In COTA, a tiny comparator judges whether sampled alternatives lead to better continuations than the actor's proposal, and repeated comparisons determine when intervention is warran"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20670","submittedDate":"2026-08-21","title":"Why2Speak: Faithful Reasoning for Abstaining Action Policies","pdf":"https://arxiv.org/pdf/2608.20670.pdf","url":"https://arxiv.org/abs/2608.20670","topics":["LLM Training","Reasoning","Fine-tuning","RL for LLM"],"authors":["Shreya Mendi","Brinnae Bent"],"tags":["LLM Training","Reasoning","Fine-tuning","RL for LLM"],"announceDate":"2026-08-24","id":"arxiv:2608.20670","abstract":"Many agentic systems must repeatedly choose between acting and abstaining, making faithful reasoning important for oversight: an explanation is useful only if it reflects the computation that produced the action. We study this problem through intervention timing in multi-party conversation, where an assistant must decide whether to speak or remain silent. This setting exposes class imbalance, asymmetric action costs, and the possibility that exposing reasoning changes the policy being audited. Using Qwen3-8B, decoded with or without chain-of-thought reasoning, we compare direct decision policies, reasoning policies, supervised fine-tuning, and reinforcement learning. We find a capability-auditability tradeoff: the strongest direct policy achieves higher quality but exposes no reasoning to inspect, while the reasoning policy provides a trace at the cost of lower performance, particularly "},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.21100","submittedDate":"2026-08-21","title":"ReFrame: Evidence-Guided Test-Time Safety Alignment in Multimodal Large Language Models","pdf":"https://arxiv.org/pdf/2608.21100.pdf","url":"https://arxiv.org/abs/2608.21100","topics":["Agent Safety","Reasoning","Evaluation","Alignment"],"authors":["Wenzheng Jiang","Xuankun Rong","Yuanzhao Zhai","Dawei Feng","Huaimin Wang"],"tags":["Agent Safety","Reasoning","Evaluation","Alignment"],"announceDate":"2026-08-24","id":"arxiv:2608.21100","abstract":"While multimodal large language models (MLLMs) extend model capabilities beyond text, they also make safety alignment increasingly challenging. Multimodal safety alignment methods must address cross-modal jailbreaks, safety-awareness failures, and over-sensitive refusals. However, existing methods often rely on retraining or internal-state inspection, limiting their applicability to deployed closed-source MLLMs and motivating test-time safety alignment. We analyze this setting and identify two key obstacles, utility dominance and reasoning inertia, which cause models to overlook latent risks or follow malicious reasoning trajectories. Guided by these insights, we propose ReFrame, a training-free multimodal input reframing framework where two agents share a lightweight locally deployed MLLM: the evidence-generation agent constructs complementary risk and utility evidence, and the rewrite-"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20797","submittedDate":"2026-08-21","title":"Automated Trajectory Evaluation for Mobile Agents via Step-Level Consequence Reasoning and Aggregation","pdf":"https://arxiv.org/pdf/2608.20797.pdf","url":"https://arxiv.org/abs/2608.20797","topics":["VLM Training","Reasoning","Evaluation","Alignment"],"authors":["Pengshuai Yang","Zijing Gao","Xue Yu","Benhui Zhuang","Bo Yuan","Junlan Feng"],"tags":["VLM Training","Reasoning","Evaluation","Alignment"],"announceDate":"2026-08-24","id":"arxiv:2608.20797","abstract":"Evaluating language-guided mobile agents has recently shifted from rule-based to model-based approaches to achieve scalable and automated assessments. However, existing holistic evaluation paradigms process entire trajectories at once, leading to substantial context overload. Moreover, they primarily focus on task completion while overlooking operational safety. To address these limitations, we introduce CRATE, a novel two-stage VLM-as-judge framework for automated mobile agent evaluation that is compatible with both open- and closed-source models. Leveraging a step-level consequence reasoning mechanism, CRATE independently extracts task-relevant visual clues and infers action-conditioned state changes at each step. The resulting step-level textual evidence is then synthesized through trajectory-level aggregation to deliver an evidence-grounded evaluation of task completion. Building upo"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20631","submittedDate":"2026-08-21","title":"Weighted Memory Tree: Remembering What Matters for Long-Horizon LLM Agents","pdf":"https://arxiv.org/pdf/2608.20631.pdf","url":"https://arxiv.org/abs/2608.20631","topics":["Tool Use","Reasoning","Planning","Memory"],"authors":["Quang Dao","Purvi Kathalkar","Kenneth Eaton"],"tags":["Tool Use","Reasoning","Planning","Memory"],"announceDate":"2026-08-24","id":"arxiv:2608.20631","abstract":"Large language model (LLM) agents have demonstrated the ability to solve multi-step tasks requiring planning, tool use, and external information access, yet growing execution histories increase inference cost and expose reasoning to outdated, irrelevant, or misleading information, potentially degrading reasoning quality. Existing memory approaches organize or compress execution histories but provide limited mechanisms for deciding which memories remain active. We introduce the, a hierarchical memory system that organizes execution into tasks, subtasks, and actions while assigning each memory a dynamic retention score. Event-based updates and selection-based decay revise these scores, allowing WMT to preserve useful information, fold completed trajectories, suppress low-utility content, and retain access to folded context. We evaluate WMT on GAIA-Text using Qwen3-8B, Gemma 4 E4B, and Llam"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20549","submittedDate":"2026-08-20","title":"Volumetric Radiology AI in the Era of Multimodal Large Language Models","pdf":"https://arxiv.org/pdf/2608.20549.pdf","url":"https://arxiv.org/abs/2608.20549","topics":["Reasoning","Planning","Evaluation","Alignment"],"authors":["Zanting Ye","Shengyuan Liu","Xin Liu","Chenhui Wang","Zhisong Wang","Jiashuai Liu","Zipei Wang","Cheng Wang","Wentao Pan","Mengjie Fang","Di Dong","Mohammad Salmanpour","Arman Rahmim","Yu Gu","Yong Xia","Hongming Shan","Yixuan Yuan","Yefeng Zheng","Lijun Lu"],"tags":["Reasoning","Planning","Evaluation","Alignment"],"announceDate":"2026-08-24","id":"arxiv:2608.20549","abstract":"Advances in multimodal large language models (MLLMs) are extending radiological artificial intelligence (AI) beyond task-specific image analysis toward multimodal understanding and reasoning. Volumetric radiology, however, presents a fundamental representational mismatch: clinical interpretation often requires full-volume spatial context and acquisition-dependent quantitative information, whereas current MLLMs are commonly conditioned on selected two-dimensional (2D) images, compressed visual representations, or report-derived text. Reliable volumetric radiology AI therefore requires representations that preserve task-relevant three-dimensional (3D) information and systems that can access, verify, and integrate this information across clinical workflows. In this Review, we examine more than 200 publications through July 2026. We organize the literature around volumetric representation an"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20390","submittedDate":"2026-06-30","title":"Ansari: A Retrieval-Grounded Islamic AI Assistant -- Architecture, Deployment, and Lessons from 140,000 Conversations","pdf":"https://arxiv.org/pdf/2608.20390.pdf","url":"https://arxiv.org/abs/2608.20390","topics":["Agentic RAG","Reasoning","Evaluation","Alignment"],"authors":["M Waleed Kadous","Amr Elsayed","Abdullah Al Nahas","Ashraf Haress"],"tags":["Agentic RAG","Reasoning","Evaluation","Alignment"],"announceDate":"2026-08-24","id":"arxiv:2608.20390","abstract":"General-purpose large language models (LLMs) are increasingly used to answer religious questions, but for Islamic content they carry two serious risks: factual fabrication (inventing Qur'anic verses or hadith) and subtle value misalignment. We present Ansari, a deployed, retrieval-grounded Islamic AI assistant that has handled more than 140,000 conversations across 25+ languages since June 2023. Ansari is built around an agentic retrieval loop: a tool-using language model issues searches against authenticated Islamic corpora -- the Qur'an, hadith collections, a multi-volume jurisprudence (fiqh) encyclopedia, and exegetical (tafsir) sources -- and answers only on the basis of what it retrieves, with citations attached for verification. We describe the system's architecture (the agent loop, the retrieval tools, the corpora, and the system prompt that encodes editorial and theological polic"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20685","submittedDate":"2026-08-21","title":"Temporal Validity on Real Software Histories: Eliminating Stale-Fact Errors in Code-Assistant Memory over GitHub Fixes","pdf":"https://arxiv.org/pdf/2608.20685.pdf","url":"https://arxiv.org/abs/2608.20685","topics":["Agentic RAG","Agentic Search","Memory","Evaluation"],"authors":["Neeraj Yadav"],"tags":["Agentic RAG","Agentic Search","Memory","Evaluation"],"announceDate":"2026-08-24","id":"arxiv:2608.20685","abstract":"Retrieval-augmented generation (RAG) has no model of time: when a fact changes across a coding session - a function is renamed, an endpoint moves, a dependency is bumped - RAG retrieves both the old and new value with near-identical similarity and cannot tell which is current, so it serves the superseded value. Paper 1 showed, on synthetic single-value benchmarks, that a deterministic (subject, relation, object) supersession memory eliminates this failure. Here we validate it end-to-end on real software history. From 707 real GitHub issues (SWE-bench Lite + Verified) we extract 130 clean atomic state transitions, a fix that changes one identifiable value from a pre-fix to a post-fix form, and render each marker-free (the stale and current statements differ only in the value). On this set, MemStrata reaches 0.91 answer accuracy versus RAG's 0.57-0.59; and, the structural result, when forc"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20372","submittedDate":"2026-06-23","title":"Edge-Based Agentic Retrieval-Augmented Generation for Autonomous FHWA Bridge Inspection Compliance","pdf":"https://arxiv.org/pdf/2608.20372.pdf","url":"https://arxiv.org/abs/2608.20372","topics":["Agentic RAG","Agentic Search","Reasoning","Planning"],"authors":["Viraj Nishesh Darji","Hemaliben Rakeshkumar Darji"],"tags":["Agentic RAG","Agentic Search","Reasoning","Planning"],"announceDate":"2026-08-24","id":"arxiv:2608.20372","abstract":"The Federal Highway Administration (FHWA) mandates that over 600,000 bridges in the United States be evaluated against the Recording and Coding Guide for the National Bridge Inventory (NBI). Manual compliance verification is labor-intensive, error-prone, and impractical in connectivity-limited field environments. This paper introduces BridgeGuard, a fully air-gapped agentic Retrieval-Augmented Generation (RAG) system for autonomous bridge inspection compliance. BridgeGuard integrates vector search over the FHWA Recording and Coding Guide with structured SQL queries against NBI tabular data, orchestrated by a stateful multi-step ReAct planning loop executing locally on commodity edge hardware. A section-aware chunking algorithm preserves hierarchical regulatory item boundaries, achieving 94.2% chunk integrity compared with 28.4% for naive fixed-size splitting. Evaluated on the full Delawa"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20362","submittedDate":"2026-06-17","title":"Multilingual Verifier Bias in RLVR: Benchmark, Rollout Diagnosis, and the Cross-Lingual Selection Bottleneck","pdf":"https://arxiv.org/pdf/2608.20362.pdf","url":"https://arxiv.org/abs/2608.20362","topics":["Post-Training","Reasoning","Evaluation","RL for LLM"],"authors":["Chenyu Zhou","Qiliang Jiang","Xu Zhou"],"tags":["Post-Training","Reasoning","Evaluation","RL for LLM"],"announceDate":"2026-08-24","id":"arxiv:2608.20362","abstract":"Reinforcement learning with verifiable rewards (RLVR) is a standard recipe for training large language models on mathematical reasoning, where an answer verifier serves as a language-neutral reward function. We show that this assumption fails in multilingual settings: an exact-match verifier turns format and script variation into language-dependent false-negative reward noise. We introduce a reusable protocol for auditing multilingual RLVR rewards: a verifier-robustness suite, a rollout-diagnosis procedure, and language-conditioned reward-error metrics for Japanese, English, and Chinese answers. On MGSM rollouts with k=8, the exact-match proxy rejects trusted-correct answers at sharply different rates by language across Qwen3-4B, Qwen3-8B, and Llama-3.1-8B-Instruct; for Qwen3-8B, the false-negative rate reaches 0.642 on JP against 0.122 on EN and 0.073 on CN. A plain-numeric probe locali"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20394","submittedDate":"2026-07-01","title":"A Factorial Ablation of a Speech-to-SFT Pipeline: Differential Effects on Data Quality and Downstream Transfer","pdf":"https://arxiv.org/pdf/2608.20394.pdf","url":"https://arxiv.org/abs/2608.20394","topics":["LLM Training","Hallucination","Evaluation","Fine-tuning"],"authors":["Wonsup Shin","Jingu Kim"],"tags":["LLM Training","Hallucination","Evaluation","Fine-tuning"],"announceDate":"2026-08-24","id":"arxiv:2608.20394","abstract":"Industry pipelines that turn speech into supervised fine-tuning (SFT) data via multi-stage refinement are increasingly adopted but, to our knowledge, have not been publicly ablated stage-by-stage, leaving each stage's marginal value unknown. We design a production-ready speech-to-SFT pipeline in which transcript refinement (Phase 0) and SFT data quality refinement (Phase 2) are independently toggleable, yielding a 2x2 factorial design. For each condition, we generate QA-form SFT data from Korean medical and finance conference recordings and fine-tune 9 models (5 LLM families, 2.4B-70B); we evaluate with four cross-provider LLM judges, a blind six-expert human evaluation, and 3 downstream MCQA benchmarks. Our central finding: under a fixed, standard SFT recipe, improvements in QA data quality do not transfer uniformly into downstream MCQA gains. 4-judge quality rises consistently, yet the"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20707","submittedDate":"2026-08-21","title":"Towards Faithful Simulation of Human Shopping Behavior","pdf":"https://arxiv.org/pdf/2608.20707.pdf","url":"https://arxiv.org/abs/2608.20707","topics":["VLM Training","Memory","Evaluation","RL for LLM"],"authors":["Jiakai Tang","Yan Mi","Jing Yu","Yang Zhang","See-Kiong Ng","Qi Cao","Fei Sun","Xu Chen","Wen Chen","Jian Wu","Han Zhu","Bo Zheng"],"tags":["VLM Training","Memory","Evaluation","RL for LLM"],"announceDate":"2026-08-24","id":"arxiv:2608.20707","abstract":"Simulating realistic user shopping behavior underpins offline evaluation and reinforcement learning in e-commerce scenarios. While recent LLM- and VLM-based simulators have made encouraging progress, reproducing a real browsing session remains difficult for two reasons. (i) Memory Challenge: a shopping session spans dozens of pages, yet existing agents either discard long-range observation histories, losing the evolving user state, or naively concatenate them, overwhelming the context window and even degrading simulation quality. (ii) Optimization Challenge: current user simulators are typically supervised to match each logged action via imitation or step-level rewards; the resulting sessions often display unrealistic patterns, such as over-exploration or excessive passivity, which per-step supervision can neither detect nor correct. To address the above challenges, we present RecVerse, "},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20814","submittedDate":"2026-08-21","title":"Enhancing Localized Reasoning for Long Video Understanding via Efficient Segment-to-Video Supervision","pdf":"https://arxiv.org/pdf/2608.20814.pdf","url":"https://arxiv.org/abs/2608.20814","topics":["Reasoning","Evaluation","Fine-tuning","RL for LLM"],"authors":["Beibei Zhang","Chao Xu","Jun Lan","Zongyi Li","Lai Wei","Huijia Zhu","Tongwei Ren"],"tags":["Reasoning","Evaluation","Fine-tuning","RL for LLM"],"announceDate":"2026-08-24","id":"arxiv:2608.20814","abstract":"Though Multimodal Large Language Models (MLLMs) have shown impressive potential in video understanding, long video understanding (LVU) remains challenging since distracting noise in complex and lengthy contexts can obscure localized details, misleading MLLMs to produce incorrect answers. Recent works mitigate these issues by incentivizing deep reasoning to include relevant evidence. However, these methods have two main problems: First, the reinforcement fine-tuning framework (RFT) they leveraged incurs substantial training overheads, including high annotation costs and complicated reward designs. Second, the self-reflective and iterative-perception mechanism in some methods causes lengthy outputs and high inference latency. To alleviate these problems, we propose a novel Segment-to-Video Supervision} method (S2V) to efficiently enhance fine-grained reasoning in LVU. Specifically, we gene"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20794","submittedDate":"2026-08-21","title":"Knowing but Not Saying: Preventing Factual Access Failures in LLM SFT via Recall-Anchored Distillation","pdf":"https://arxiv.org/pdf/2608.20794.pdf","url":"https://arxiv.org/abs/2608.20794","topics":["LLM Training","Evaluation","Fine-tuning"],"authors":["Haodong Chen","Yadong Wang","Shengtao Wen","Dong Liang","Xiang Chen"],"tags":["LLM Training","Evaluation","Fine-tuning"],"announceDate":"2026-08-24","id":"arxiv:2608.20794","abstract":"Supervised fine-tuning (SFT) can degrade factual behavior outside the target domain. This degradation is often described as catastrophic forgetting, yet open-ended factual failures do not necessarily imply that the underlying facts have been erased. In this work, we identify a more specific phenomenon, factual access failure: after domain SFT, models can still recognize or rank the correct answer under constrained evaluation, while failing to produce it in closed-book generation. Through benchmark-level comparisons, same-fact multiple-choice and generation probes, and failure-mode analysis, we show that SFT-induced factual degradation reflects both genuine wrong-answer generations and expression-level failures such as verbosity, formatting mismatch, and exact-match artifacts. To address this problem, we introduce Recall-Anchored Distillation (RAD), a base-anchored self-distillation objec"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20735","submittedDate":"2026-08-21","title":"ForeTime-VLA: Causal Future-Token Distillation from a World Action Model for Conveyor-Belt Manipulation","pdf":"https://arxiv.org/pdf/2608.20735.pdf","url":"https://arxiv.org/abs/2608.20735","topics":["VLM Training","Evaluation","Fine-tuning"],"authors":["Siyuan Ma","Yutian Zhang","Boshi Zhang","Qinglian Wu","Jiaqi Zhai","Dong Wei","Xiaojin Huang"],"tags":["VLM Training","Evaluation","Fine-tuning"],"announceDate":"2026-08-24","id":"arxiv:2608.20735","abstract":"Manipulating moving objects requires a policy to anticipate contact events, yet vision-language-action (VLA) policies are commonly fine-tuned from the current observation alone. World action models (WAMs) learn predictive dynamics, but running a video-scale teacher or explicitly imagining future frames at deployment is costly. We introduce ForeTime-VLA, a dense pi0.5 policy that distills a future-aware, action-equivalent representation from a frozen Fast-WAM-derived teacher while remaining causal at inference. Offline, current and future video latents are compressed into a whitened 64-D target. Online, an eight-frame history encoder predicts this target together with manipulation phase and normalized time-to-transition. Four future tokens and one phase token condition the VLM prefix, while the predicted future and transition horizon condition the action expert. Training retains the origi"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20611","submittedDate":"2026-08-20","title":"Difficulty-Aware Semantic-ID Optimization for Generative Recommendation","pdf":"https://arxiv.org/pdf/2608.20611.pdf","url":"https://arxiv.org/abs/2608.20611","topics":["Post-Training","LLM Training","Evaluation"],"authors":["Xin Yu","Stephen Li","Sina Aghaei","Zifan Zhu","Jiamu Bai","Guanjie Huang","Bo Peng","Yiyao Liu","Lingzhou Xue"],"tags":["Post-Training","LLM Training","Evaluation"],"announceDate":"2026-08-24","id":"arxiv:2608.20611","abstract":"Semantic-ID-based generative recommendation casts retrieval and ranking as autoregressive generation over hierarchical item identifiers. A common recipe is SFT followed by GRPO, yet vanilla GRPO is poorly matched to this tree-structured task. Under the frozen SFT checkpoint, the exact target is absent from the first 16 candidates of the 50-beam constrained ranking for many prompts, and in harder cases none of these candidates enters the target SID branch. This prompt-level diagnostic motivates a training concern: when on-policy GRPO groups are similarly target-missing, item-level rewards may produce weak or degenerate reward variation even if some candidates follow part of the target path. We propose Difficulty-Aware Semantic-ID Optimization (DASO), a tree-aware post-training method that addresses this failure mode as an online rollout-allocation problem. Instead of using fixed difficult"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20918","submittedDate":"2026-08-21","title":"UpgradeBench: A Decision-Centric Benchmark for Upgrading Fine-Tuned LLM Specialists","pdf":"https://arxiv.org/pdf/2608.20918.pdf","url":"https://arxiv.org/abs/2608.20918","topics":["LLM Training","Evaluation","Fine-tuning"],"authors":["Ye Chen","Weining Zhang"],"tags":["LLM Training","Evaluation","Fine-tuning"],"announceDate":"2026-08-24","id":"arxiv:2608.20918","abstract":"Organizations maintain task-specific adapters for open-weight language models, and each new base-model release forces a migration decision: retain existing specialists, port adapters, refresh from preserved behavior, or retrain. Prior transfer work evaluates isolated model pairs, without studying these choices across real model release sequences. We present UpgradeBench, a decision-driven longitudinal benchmark covering four consecutive Qwen releases, one continuation checkpoint, six tasks, and two model sizes, augmented by OLMo checkpoints with known training lineage. The benchmark disentangles three core questions: whether a new checkpoint improves fixed-recipe retrained specialist performance, whether specialization assets transfer across versions, and what recovery resources are usable. We observe upgrade gains differ across task-scale-release episodes: some retrained baselines impro"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.21357","submittedDate":"2026-08-21","title":"VIALS: A Benchmark for Visual Interpretation of Artifacts in the Life Sciences","pdf":"https://arxiv.org/pdf/2608.21357.pdf","url":"https://arxiv.org/abs/2608.21357","topics":["VLM Training","Reasoning","Evaluation"],"authors":["Elaine Lau","Thanuka Udumulla","Lee Izhaki-Tavor","Francisco Guzmán","Nicholas Magazine","Jonas Mueller"],"tags":["VLM Training","Reasoning","Evaluation"],"announceDate":"2026-08-24","id":"arxiv:2608.21357","abstract":"In professional life sciences workflows, scientists routinely interpret visual artifacts (gel blots, microscopy images, plasmid maps, flow cytometry plots, molecular structures, ...) to inform research decisions. We introduce VIALS, a visual question-answering benchmark with 161 such interpretation tasks, spanning the types of artifacts examined throughout experimental workflows in the biotech industry (rather than polished figures from publications and textbooks). While frontier vision-language models can now fluently describe natural images, we find that they are unable to accurately interpret these scientific images, reflecting limitations in domain knowledge and domain-specific visual reasoning capabilities. In contrast, scientists with relevant domain expertise find these visual interpretation tasks straightforward. AI that cannot similarly interpret such images will have limited ut"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.21208","submittedDate":"2026-08-21","title":"Specification Portability Across LLM Development Agents: Cross-Agent Compatibility in Specification-Driven Software Migration","pdf":"https://arxiv.org/pdf/2608.21208.pdf","url":"https://arxiv.org/abs/2608.21208","topics":["Agentic Search","Multi-Agent","Evaluation"],"authors":["Oleg Grynets","Oleksii Ilchuk","Dariia Zatulna","Vasyl Lyashkevych"],"tags":["Agentic Search","Multi-Agent","Evaluation"],"announceDate":"2026-08-24","id":"arxiv:2608.21208","abstract":"This paper investigates cross-agent specification portability using Oracle-to-PostgreSQL migration as a controlled software transformation task. The study combines two experimental stages. First, a specification-first migration pipeline was evaluated on 1,006 PL/SQL files, of which 623 were successfully regenerated and 380 generated scripts executed successfully in PostgreSQL 16. Second, cross-agent experiments were conducted on a dataset of 1,802 Oracle scripts with corresponding PostgreSQL implementations using Amazon Kiro, Google Gemini, and GitHub Copilot, with Claude Code and Cursor included in the initial single-agent evaluation. Native and foreign specifications were assessed using Token F1, exact match, SQL syntax validity, AST exact match, AST mean similarity, and immediate runnability. The results show that specification size alone does not predict implementation quality and th"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20743","submittedDate":"2026-08-21","title":"Is Multimodal Speculative Decoding Ready for Diffusion-Based Parallel Drafting? A Survey and Empirical Diagnosis","pdf":"https://arxiv.org/pdf/2608.20743.pdf","url":"https://arxiv.org/abs/2608.20743","topics":["Reasoning","Evaluation","Alignment"],"authors":["Yantao Li","Huanlin Gao","Fang Zhao","Chao Tan","Qiang Hui","Shuting Liu","Fuyuan Shi","Ting Lu","Shaoan Zhao","Xueqiang Guo","Xinpei Su","Jianbing Zhang","Xinyu Dai","Kai Wang","Shiguo Lian"],"tags":["Reasoning","Evaluation","Alignment"],"announceDate":"2026-08-24","id":"arxiv:2608.20743","abstract":"Speculative decoding accelerates autoregressive generation by allowing a lightweight drafter to propose future tokens while a target model verifies them in parallel. Its lossless guarantee has motivated a line of work that pushes the drafter itself toward parallel generation. The most recent paradigm is block-parallel generative drafting, including diffusion-based methods such as DFlash and DSpark, achieving up to 3.6x speedup on common daily chatting tasks. While this transition is well studied in text-only LLMs, its applicability to multimodal models remains an open question. Existing multimodal speculative decoding efforts focus on input compression, adapter alignment, candidate coverage, or modality-specific verification; however, block-parallel generative drafting remains largely unexplored. To bridge this gap, this paper combines a modality-centered survey with a cross-architecture"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20661","submittedDate":"2026-08-21","title":"Auditable by Construction: An Ontology-Driven Framework for Trustworthy LLM Analytics in Enterprise Finance","pdf":"https://arxiv.org/pdf/2608.20661.pdf","url":"https://arxiv.org/abs/2608.20661","topics":["Agentic RAG","Agentic Search","Planning"],"authors":["Sergiy Lunyakin"],"tags":["Agentic RAG","Agentic Search","Planning"],"announceDate":"2026-08-24","id":"arxiv:2608.20661","abstract":"Enterprise adoption of large language models in finance is constrained less by fluency than by trust: in Financial Planning and Analysis (FP&A) and other regulated workflows, an answer is usable only if it is traceable to authoritative sources and auditable after the fact. This paper argues that retrieval-augmented generation for enterprise finance should be evaluated on auditability alongside accuracy, and presents the Knowledge-Driven Analytics Framework (KDAF), which builds ontology-driven knowledge systems through six iterative stages and retrieves evidence via Context-Aware Relevance Propagation (CARP), so that every retrieved fact carries its relationship type, confidence, and source lineage. An evaluation on FinanceBench (145 questions) compares KDAF against zero-context inference, BM25, concept-weighted lexical retrieval, and ungrounded graph traversal. First, retrieval is necess"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.21252","submittedDate":"2026-08-21","title":"EnSI-RAG: Entity-Structure-Indexed Retrieval-Augmented Generation for Long-Document Question Answering","pdf":"https://arxiv.org/pdf/2608.21252.pdf","url":"https://arxiv.org/abs/2608.21252","topics":["Agentic RAG","Agentic Search","Reasoning"],"authors":["Xuanyu Meng","Jiashuo Sun","Jash Rajesh Parekh","Jiawei Han"],"tags":["Agentic RAG","Agentic Search","Reasoning"],"announceDate":"2026-08-24","id":"arxiv:2608.21252","abstract":"Question answering (QA) over long, connected documents remains challenging because relevant evidence may span multiple entities and their relationships. Existing retrieval-augmented generation (RAG) methods typically index documents as raw chunks and retrieve them through embedding similarity. Their performance degrades when chunk boundaries separate entities from supporting evidence or when a question requires multi-hop reasoning across the corpus. We propose EnSI-RAG (Entity-Structure-Indexed Retrieval-Augmented Generation), a framework that constructs a query-independent, entity-centered index. Each record (e, t, k, v) represents an entity e, its type t, a semantic category k in {property, relation, aspect}, and a value v, while retaining links to the original source passages. At query time, these records serve as retrieval handles, and an LLM synthesizes the retrieved passages into t"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20341","submittedDate":"2026-05-05","title":"SDAD: Spec-Driven Agentic Development for the AI-Native SDLC","pdf":"https://arxiv.org/pdf/2608.20341.pdf","url":"https://arxiv.org/abs/2608.20341","topics":["Multi-Agent","Reasoning","Code Agent"],"authors":["Vu Hung Nguyen","Thanh Nguyen"],"tags":["Multi-Agent","Reasoning","Code Agent"],"announceDate":"2026-08-24","id":"arxiv:2608.20341","abstract":"Frontier coding agents backed by large language models with context windows from hundreds of thousands to millions of tokens are restructuring the Software Development Life Cycle (SDLC). Rich context handling and multi-step reasoning now allow substantial Functional Requirement Documents (FRDs) and repository context to be ingested in a single workflow, making specification quality the execution fuel for autonomous delivery. This report formalises Spec-Driven Agentic Development (SDAD) as a synthesis of disciplined up-front formalisation and high-velocity implementation: intent capture, machine-readable specification, agentic synthesis, and independent multi-agent verification under human sign-off. We revisit the historical pendulum between Waterfall and Agile, introduce AI-code as a fourth production paradigm, and compare Human-Agile (circa 2020) with Agentic-SDAD (circa 2026) across ar"},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20414","submittedDate":"2026-08-15","title":"StateSight: Benchmarking Latent Spatial-State Reconstruction in Vision-Language Models","pdf":"https://arxiv.org/pdf/2608.20414.pdf","url":"https://arxiv.org/abs/2608.20414","topics":["VLM Training","Reasoning","Evaluation"],"authors":["Michelle Lin"],"tags":["VLM Training","Reasoning","Evaluation"],"announceDate":"2026-08-24","id":"arxiv:2608.20414","abstract":"Vision-language models are increasingly used for multimodal question answering, yet their ability to reconstruct latent spatial structure from a single image remains difficult to isolate. Broad benchmarks often combine perception, optical character recognition, domain knowledge, linguistic priors, and reasoning in the same evaluation. We introduce StateSight, a procedurally generated benchmark for cube-net opposite-face reasoning, occluded cube-tower counting, and 4-neighbor connected-component counting. Each task family contains 300 single-image prompts with deterministic oracle labels and exact-match scoring. OpenAI GPT-5.5, using the API model identifier gpt-5.5, achieved 59.3%, 33.3%, and 28.3% accuracy across the three tasks, while Claude Sonnet 5 achieved 53.3%, 18.7%, and 7.3%. All final direct runs had zero format errors. A 30-participant human baseline on 60 items exceeded both "},{"source":"arxiv","date":"2026-08-24","upvotes":0,"arxiv":"https://arxiv.org/abs/2608.20845","submittedDate":"2026-08-21","title":"RAG Deserves an Index: Why Ingest-Time Compilation Beats Query-Time Interpretation","pdf":"https://arxiv.org/pdf/2608.20845.pdf","url":"https://arxiv.org/abs/2608.20845","topics":["Agentic RAG","Agentic Search","Planning"],"authors":["Kyle Wild","Yusuke Takahashi","Asako Uraki"],"tags":["Agentic RAG","Agentic Search","Planning"],"announceDate":"2026-08-24","id":"arxiv:2608.20845","abstract":"Nearly every retrieval-augmented question-answering system in production ships with a hidden interpreter: on each query a language model re-derives the meaning of raw corpus text and then throws that work away. Cheaper models do not close the gap: per-token prices have fallen by orders of magnitude while inference spend has risen, because context volume grows faster than prices fall. This is the modern equivalent of the full-table scan, and the remedy is the one databases found fifty years ago: do the expensive work once, at write time, into a maintained structure that makes reads cheap. A corpus whose read pattern is known before it ever meets a user can and should be indexed too. We call the paradigm ingest-time semantic compilation (ISC): compile a corpus's meaning into a queryable substrate with two coupled layers - incrementally maintained embeddings, and atomic claims whose provena"}],"archive":[],"latestPath":"data/latest.json"};
